            "output": "<path>/Users/rohithpapani/ERP_mem/parking/app/ticket.py</path>\n<type>file</type>\n<content>\n1: \"\"\"Core MPS-2 engine: issuing OPEN parking tickets at the entry gate.\n2: \n3: One entry transaction creates exactly one unique OPEN ticket, bumps the\n4: occupied-space counter exactly once, and is idempotent under a client-supplied\n5: idempotency key. Entry is rejected with :class:`LotFullError` when occupancy\n6: equals configured capacity. Ticket creation and the occupancy increment are\n7: atomic in :meth:`TicketService.enter` — a failed or full entry leaves both the\n8: store and the occupancy counter unchanged.\n9: \"\"\"\n10: \n11: from __future__ import annotations\n12: \n13: from dataclasses import dataclass\n14: from datetime import datetime, timezone\n15: from typing import Callable\n16: \n17: from .config import ParkingConfiguration\n18: \n19: STATUS_OPEN = \"OPEN\"\n20: \n21: \n22: class LotFullError(Exception):\n23:     \"\"\"Raised when no parking capacity remains for an entry request.\"\"\"\n24: \n25: \n26: def _utcnow() -> datetime:\n27:     return datetime.now(timezone.utc)\n28: \n29: \n30: def normalize_vehicle_number(raw: str) -> str:\n31:     \"\"\"Trim surrounding whitespace and uppercase a vehicle number.\"\"\"\n32:     if not isinstance(raw, str):\n33:         raise ValueError(f\"vehicle_number must be a string, got {type(raw).__name__}\")\n34:     normalized = raw.strip().upper()\n35:     if not normalized:\n36:         raise ValueError(\"vehicle_number must not be blank\")\n37:     return normalized\n38: \n39: \n40: @dataclass(frozen=True)\n41: class ParkingTicket:\n42:     \"\"\"An OPEN parking ticket issued at the entry gate.\n43: \n44:     Attributes:\n45:         ticket_id: Unique external ticket identifier.\n46:         vehicle_number: Normalized (trimmed, uppercased) vehicle number.\n47:         entry_time: Server-generated entry timestamp (timezone-aware UTC).\n48:         status: Ticket state; ``OPEN`` for newly issued tickets.\n49:     \"\"\"\n50: \n51:     ticket_id: str\n52:     vehicle_number: str\n53:     entry_time: datetime\n54:     status: str = STATUS_OPEN\n55: \n56:     def __post_init__(self) -> None:\n57:         if not self.ticket_id:\n58:             raise ValueError(\"ticket_id must not be empty\")\n59: \n60: \n61: class TicketStore:\n62:     \"\"\"In-memory parking-ticket store keyed by ticket ID and idempotency key.\"\"\"\n63: \n64:     def __init__(self) -> None:\n65:         self._by_id: dict[str, ParkingTicket] = {}\n66:         self._by_key: dict[str, ParkingTicket] = {}\n67: \n68:     def by_id(self, ticket_id: str) -> ParkingTicket | None:\n69:         return self._by_id.get(ticket_id)\n70: \n71:     def by_key(self, idempotency_key: str) -> ParkingTicket | None:\n72:         return self._by_key.get(idempotency_key)\n73: \n74:     def add(self, ticket: ParkingTicket, *, idempotency_key: str | None) -> None:\n75:         if ticket.ticket_id in self._by_id:\n76:             raise ValueError(f\"duplicate ticket_id {ticket.ticket_id!r}\")\n77:         if idempotency_key is not None and idempotency_key in self._by_key:\n78:             raise ValueError(f\"duplicate idempotency_key {idempotency_key!r}\")\n79:         self._by_id[ticket.ticket_id] = ticket\n80:         if idempotency_key is not None:\n81:             self._by_key[idempotency_key] = ticket\n82: \n83: \n84: class Occupancy:\n85:     \"\"\"Monotonic occupied-space counter shared by entry and occupancy services.\"\"\"\n86: \n87:     def __init__(self) -> None:\n88:         self._count = 0\n89: \n90:     @property\n91:     def count(self) -> int:\n92:         return self._count\n93: \n94:     def increment(self) -> None:\n95:         self._count += 1\n96: \n97: \n98: class TicketService:\n99:     \"\"\"Entry-gate service that issues OPEN tickets atomically.\n100: \n101:     Args:\n102:         configuration: Active parking configuration providing capacity.\n103:         now: Injectable clock returning the server entry time.\n104:         new_ticket_id: Injectable unique-ID generator (defaults to ``T-1``,\n105:             ``T-2``, ... consumed only for successfully issued tickets).\n106:     \"\"\"\n107: \n108:     def __init__(\n109:         self,\n110:         configuration: ParkingConfiguration,\n111:         *,\n112:         now: Callable[[], datetime] | None = None,\n113:         new_ticket_id: Callable[[], str] | None = None,\n114:     ) -> None:\n115:         self._configuration = configuration\n116:         self._store = TicketStore()\n117:         self._occupancy = Occupancy()\n118:         self._now = now if now is not None else _utcnow\n119:         self._issued = 0\n120:         self._new_ticket_id = (\n121:             new_ticket_id if new_ticket_id is not None else self._next_ticket_id\n122:         )\n123: \n124:     def _next_ticket_id(self) -> str:\n125:         self._issued += 1\n126:         return f\"T-{self._issued}\"\n127: \n128:     @property\n129:     def occupancy(self) -> int:\n130:         \"\"\"Current number of occupied spaces.\"\"\"\n131:         return self._occupancy.count\n132: \n133:     def enter(\n134:         self,\n135:         vehicle_number: str,\n136:         *,\n137:         idempotency_key: str | None = None,\n138:     ) -> ParkingTicket:\n139:         \"\"\"Process one entry request and issue an OPEN ticket.\n140: \n141:         Idempotent: a repeat request carrying the same idempotency key returns\n142:         the existing ticket without touching occupancy. Raises\n143:         :class:`LotFullError` when occupancy already equals capacity.\n144:         \"\"\"\n145:         vehicle = normalize_vehicle_number(vehicle_number)\n146:         key = self._normalize_key(idempotency_key)\n147:         if key is not None:\n148:             existing = self._store.by_key(key)\n149:             if existing is not None:\n150:                 return existing\n151:         if self._occupancy.count >= self._configuration.capa